'use client'

import { useMemo, useState } from 'react'
import { ArrowDown, ArrowRight, Check, Play, Sprout } from 'lucide-react'

const scripts = [
  ['Cosechadora.cs', 'Lógica de la máquina líder y recorrido por surcos.'],
  ['TractorAlLado.cs', 'Seguimiento lateral del tractor y remolque.'],
  ['ParcelaSpawner.cs', 'Poblado procedural de terreno y espigas.'],
  ['PanelConfiguracionUI.cs', 'Controles para preparar cada simulación.'],
  ['ConfiguracionSimulacion.cs', 'Puente de datos entre escenas de Unity.'],
  ['SelectorModelo.cs', 'Selección del modelo 3D de cada máquina.'],
  ['CameraMove.cs', 'Cámaras de observación del sistema.'],
]

const models = ['Tractor', 'Remolque', 'Cosechadora', 'Granja', 'Silo', 'Espantapájaros', 'Barda', 'Árboles']

function SectionLabel({ children }: { children: string }) {
  return <p className="section-label">{children}</p>
}

function FurrowDiagram({ grid = false, inset = false }: { grid?: boolean; inset?: boolean }) {
  const lanes = Array.from({ length: 6 }, (_, i) => 44 + i * 32)
  return (
    <svg viewBox="0 0 280 190" role="img" aria-label="Diagrama de recorrido de cosecha" className="diagram-svg">
      <rect x="18" y="15" width="244" height="160" fill="#EAF2E5" stroke="#367C2B" strokeWidth="2" />
      {inset && <rect x="34" y="31" width="212" height="128" fill="none" stroke="#6B4F2A" strokeDasharray="5 4" strokeWidth="2" />}
      {grid && Array.from({ length: 5 }, (_, i) => <line key={`h${i}`} x1="18" y1={47 + i * 28} x2="262" y2={47 + i * 28} stroke="#9DB69A" strokeWidth="1" />)}
      {grid && Array.from({ length: 7 }, (_, i) => <line key={`v${i}`} x1={18 + i * 40.6} y1="15" x2={18 + i * 40.6} y2="175" stroke="#9DB69A" strokeWidth="1" />)}
      {lanes.map((x, i) => (
        <g key={x}>
          <line x1={x} y1="34" x2={x} y2="156" stroke={grid && i !== 1 && i !== 2 ? '#AFC7A9' : '#FFDE00'} strokeWidth={grid && i !== 1 && i !== 2 ? 1 : 3} />
          {!grid && <path d={i % 2 === 0 ? `M${x} 34 C ${x + 21} 34, ${x + 21} 15, ${x + 32} 15` : `M${x} 156 C ${x + 21} 156, ${x + 21} 175, ${x + 32} 175`} fill="none" stroke="#FFDE00" strokeWidth="3" />}
        </g>
      ))}
      {grid && <><rect x="58" y="43" width="40" height="28" fill="#FFDE00" opacity=".85" /><rect x="98" y="71" width="40" height="28" fill="#FFDE00" opacity=".85" /><rect x="58" y="99" width="40" height="28" fill="#FFDE00" opacity=".85" /><rect x="98" y="127" width="40" height="28" fill="#FFDE00" opacity=".85" /></>}
      <circle cx="44" cy="34" r="4" fill="#1B3D1A" />
    </svg>
  )
}

function CompareDiagram({ alternating }: { alternating: boolean }) {
  return <svg viewBox="0 0 180 130" role="img" aria-label={alternating ? 'Carriles alternados' : 'Recorrido secuencial'} className="diagram-svg small-diagram">
    <rect x="15" y="12" width="150" height="106" fill="#EAF2E5" stroke="#367C2B" />
    {[45, 75, 105, 135].map((x, i) => <g key={x}><line x1={x} y1="24" x2={x} y2="106" stroke="#FFDE00" strokeWidth="3" /><text x={x} y="116" textAnchor="middle" fill="#2B2B2B" fontSize="9">{i + 1}</text><path d={alternating && i % 2 === 0 ? `M${x} 24 L${x} 106` : alternating ? `M${x} 106 L${x} 24` : `M${x} 24 L${x} 106`} stroke="#1B3D1A" strokeWidth="1" markerEnd="url(#arrow)" /></g>)}
    <defs><marker id="arrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0,0 L5,2.5 L0,5" fill="#1B3D1A" /></marker></defs>
  </svg>
}

export default function Page() {
  const [width, setWidth] = useState(200)
  const [length, setLength] = useState(500)
  const [cut, setCut] = useState(9)
  const [speed, setSpeed] = useState(6)
  const lanes = Math.ceil(width / cut)
  const distance = (lanes * length + lanes * cut * Math.PI / 2) / 1000
  const hours = distance / speed
  const area = width * length / 10000
  const metrics = useMemo(() => ({ lanes, distance, hours, area }), [lanes, distance, hours, area])

  return <main>
    <nav className="top-nav"><a href="#inicio" className="brand"><Sprout size={22} /> AGENTIC<span>HARVEST</span></a><div className="nav-links"><a href="#algoritmo">Algoritmo</a><a href="#calculadora">Calculadora</a><a href="#equipo">Equipo</a><a href="#roadmap">Roadmap</a></div></nav>
    <section id="inicio" className="hero section-dark"><div className="container hero-grid"><div><SectionLabel>Reto de socio formador John Deere</SectionLabel><h1>Simulación multiagente de cosecha autónoma</h1><p className="hero-copy">Una flota de cosechadoras y tractores coordinándose para cosechar un campo de trigo, simulada en Unity 6.</p><a href="#algoritmo" className="button button-yellow">Cómo funciona <ArrowDown size={18} /></a></div><div className="video-placeholder"><Play size={38} fill="currentColor" /><span>Demo de simulación Unity 6</span></div></div><div className="container metrics"><div><strong>4</strong><span>cámaras</span></div><div><strong>15 s</strong><span>por vuelta</span></div><div><strong>1,200+</strong><span>espigas simuladas</span></div></div></section>

    <section id="algoritmo" className="section section-bone"><div className="container"><SectionLabel>01 / Cómo funciona</SectionLabel><h2>El algoritmo detrás de la cosecha</h2><p className="intro">La demo muestra el resultado. Aquí explicamos las decisiones que permiten que cada máquina se mueva de forma predecible y eficiente.</p><div className="algorithm-feature card"><div><h3>Recorrido en surco <em>(boustrophedon)</em></h3><p>La cosechadora divide el campo en carriles paralelos y alterna el sentido en cada pasada. Los giros amplios aprovechan la cabecera sin invadir el siguiente surco.</p></div><FurrowDiagram /></div><div className="compare-grid"><article className="card"><CompareDiagram alternating={false} /><h3>Secuencial</h3><p>Entrar y salir del mismo lado fuerza giros innecesarios y aumenta el tiempo muerto.</p></article><article className="card"><CompareDiagram alternating /><h3>Carriles alternados</h3><p>El patrón alternado evita que una máquina real tenga que girar demasiado cerrado.</p></article></div><div className="diagram-grid"><article className="card"><FurrowDiagram inset /><h3>Recorte de cabecera</h3><p>Una frontera interior reserva espacio para que la máquina pueda girar alrededor del campo.</p></article><article className="card"><FurrowDiagram grid /><h3>Rejilla espacial</h3><p>En lugar de consultar miles de espigas por frame, solo se revisan las celdas vecinas al cabezal.</p></article></div></div></section>

    <section id="arquitectura" className="section section-green"><div className="container"><SectionLabel>02 / Arquitectura</SectionLabel><h2>De la configuración al campo</h2><div className="flow">{['Panel de configuración', 'ConfiguracionSimulación', 'Escena de simulación', 'Cosechadora (líder)', 'Tractor (seguidor)'].map((item, i) => <div className="flow-item" key={item}><div>{item}</div>{i < 4 && <ArrowDown size={18} />}</div>)}</div><div className="script-grid">{scripts.map(([name, desc]) => <article className="script-card" key={name}><code>{name}</code><p>{desc}</p></article>)}</div><div className="chips">{['Unity 6', 'URP', 'Input System', 'Shader Graph', 'NavMesh', 'TextMeshPro'].map(x => <span key={x}>{x}</span>)}</div></div></section>

    <section id="calculadora" className="section section-light"><div className="container"><SectionLabel>03 / Calculadora</SectionLabel><h2>Prueba las mismas fórmulas</h2><p className="intro">Ajusta el terreno y observa cómo cambia la estrategia de cosecha en tiempo real.</p><div className="calculator"><div className="controls">{([['Ancho del campo (m)', width, 50, 500, setWidth], ['Largo del campo (m)', length, 50, 800, setLength], ['Ancho de corte (m)', cut, 3, 15, setCut], ['Velocidad (km/h)', speed, 2, 12, setSpeed]] as const).map(([label, value, min, max, setter]) => <label key={label}>{label}<output>{value}</output><input type="range" min={min} max={max} value={value} onChange={e => setter(Number(e.target.value))} /></label>)}<p className="formula-note">Las mismas fórmulas que corren en la simulación.</p></div><div className="calc-results"><div className="calc-preview"><FurrowDiagram /></div><div className="result-grid"><div><strong>{metrics.lanes}</strong><span>carriles</span></div><div><strong>{metrics.distance.toFixed(2)}</strong><span>distancia total (km)</span></div><div><strong>{metrics.hours.toFixed(2)}</strong><span>tiempo estimado (h)</span></div><div><strong>{metrics.area.toFixed(2)}</strong><span>área cosechada (ha)</span></div></div></div></div></div></section>

    <section id="equipo" className="section section-bone"><div className="container"><SectionLabel>04 / Equipo y modelado 3D</SectionLabel><h2>Todo empieza en nuestro propio modelo</h2><p className="intro">Cada modelo 3D fue construido por el equipo. No usamos assets de tienda: diseñamos el campo para que el algoritmo tuviera un escenario realista.</p><div className="model-grid">{models.map((model, i) => <article className="model-card" key={model}><div className={`model-art art-${i}`}><span>{String(i + 1).padStart(2, '0')}</span></div><h3>{model}</h3><p>Modelo propio del equipo</p></article>)}</div><div className="team-list">{[['Andrés', 'tractor, remolque, llantas, granja, barda'], ['Samantha', 'silo, modelo de trigo'], ['Andrea', 'espantapájaros, piso de rocas, pasto, panel de configuración'], ['Iván', 'elementos de escena'], ['Marcelo', 'elementos de escena']].map(([name, work]) => <div key={name}><strong>{name}</strong><span>{work}</span></div>)}</div></div></section>

    <section id="roadmap" className="section section-dark roadmap"><div className="container"><SectionLabel>05 / Roadmap</SectionLabel><h2>Del prototipo a la flotilla</h2><div className="timeline"><div><span className="marker done"><Check size={15} /></span><h3>Entregado</h3><ul>{['Ruta procedural', 'Corte optimizado con rejilla espacial', 'Tractor acompañante', 'Poblado procedural del terreno', 'Panel de configuración', '4 cámaras'].map(x => <li key={x}>{x}</li>)}</ul></div><div><span className="marker next"><ArrowRight size={15} /></span><h3>Siguiente</h3><ul>{['Tractor como agente autónomo real', 'Instanciar N máquinas según configuración', 'Evasión de obstáculos con NavMesh', 'Métricas de eficiencia por máquina'].map(x => <li key={x}>{x}</li>)}</ul></div></div><p className="business">La agricultura de precisión abre una conversación concreta: ahorro de combustible, reducción de solape de pasadas y menor tiempo muerto para toda la flotilla.</p></div></section>

    <footer><div className="container footer-grid"><div><div className="brand"><Sprout size={22} /> MULTIAGENTES<span>RETO</span></div><p>Presentado a John Deere como socio formador</p></div><div><p>Universidad · Ingeniería</p><p>Curso de simulación y sistemas autónomos</p></div><a href="https://github.com" className="github-link">Repositorio GitHub <ArrowRight size={16} /></a></div></footer>
    <div className="mobile-nav"><a href="#inicio">Inicio</a><a href="#algoritmo">Algoritmo</a><a href="#calculadora">Calculadora</a><a href="#equipo">Equipo</a></div>
  </main>
}
